 "content": "def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    sr=next(r for r in range(h) for c in range(w) if g[r][c]==2)
    sc=next(c for c in range(w) if g[sr][c]==2)
    # Paint the two diagonal rays from the marker, preserving the 8 pattern.
    for r in range(sr+1,h):
        d=r-sr
        for c in (sc-d,sc+d):
            if 0<=c<w and g[r][c]==0:
                g[r][c]=2
    # Each row of the expanding triangular field is filled between the rays.
    # continue the beam as a solid wedge.
    for r in range(sr+1,h):
        d=r-sr
        for c in range(max(0,sc-d),min(w,sc+d+1)):
            if g[r][c]==0: g[r][c]=2
    return g
