 "content": "def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    from collections import deque
    q=deque()
    seen=set()
    for r in range(h):
        for c in range(w):
            if g[r][c]==2:
                q.append((r,c)); seen.add((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and g[nr][nc]!=8 and (nr,nc) not in seen:
                seen.add((nr,nc));q.append((nr,nc))
    for r,c in seen:
        if g[r][c]==0: g[r][c]=2
    return g
