    holes = {r: [c for c, v in enumerate(g[r]) if v == 0] for r in bars}
    # The 2 traces corridors between successive wall openings. Carry each
    # opening downward, and join the next set of openings on the row above it.
    for i, r in enumerate(bars):
        hs = holes[r]
        for c in hs:
            g[r][c] = 2
        if hs and r > 0:
            for c in range(min(hs), max(hs) + 1):
                if g[r - 1][c] == 0:
                    g[r - 1][c] = 2
        if i + 1 < len(bars) and hs:
            next_r = bars[i + 1]
            for rr in range(r + 1, next_r):
                for c in hs:
                    if g[rr][c] == 0:
                        g[rr][c] = 2
    # Continue the channels opened in the final wall to the bottom edge.
    if bars:
        r = bars[-1]
        for c in holes[r]:
            for rr in range(r + 1, h):
                if g[rr][c] == 0:
                    g[rr][c] = 2
    return g
