    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    walls = [r for r, row in enumerate(g) if 8 in row]
    holes = {r: [c for c, v in enumerate(g[r]) if v == 0] for r in walls}
    seed = next((r, c) for r in range(h) for c in range(w) if g[r][c] == 2)
    sr, sc = seed

    # Color the openings in each horizontal barrier and connect the openings
    # across the clear band immediately above it.
    for i, r in enumerate(walls):
        hs = holes[r]
        for c in hs:
            g[r][c] = 2
        if i > 0 and hs:
            prev = walls[i - 1]
            for rr in range(prev + 1, r):
                for c in range(min(hs), max(hs) + 1):
                    if g[rr][c] == 0:
                        g[rr][c] = 2
        elif r > 0 and hs:
            # Connect the initial marker to the first barrier's opening.
            lo, hi = min(hs), max(hs)
            for c in range(min(lo, sc), max(hi, sc) + 1):
                if g[r - 1][c] == 0:
                    g[r - 1][c] = 2

    # Between barriers, the openings leave vertical tracks; the wave broadens
    # in the blank rows before meeting the next barrier.
    for i in range(len(walls) - 1):
        r, nr = walls[i], walls[i + 1]
        hs = holes[r]
        if not hs:
            continue
        lo, hi = min(hs), max(hs)
        for rr in range(r + 1, nr):
            spread = rr - r - 1
            left, right = max(0, lo - 2 * spread), min(w - 1, hi + 2 * spread)
            for c in range(left, right + 1):
                if g[rr][c] == 0:
                    g[rr][c] = 2

    if walls:
        r = walls[-1]
        for c in holes[r]:
            for rr in range(r + 1, h):
                if g[rr][c] == 0:
                    g[rr][c] = 2
    return g
