 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seed = next((r, c) for r in range(h) for c in range(w) if g[r][c] == 2)
    sr, sc = seed
    # Horizontal barrier rows have openings; color the openings. Between them,
    # carry the beam along the open channels and widen at each successive row.
    walls = [r for r, row in enumerate(g) if 8 in row]
    for r in walls:
        for c, v in enumerate(g[r]):
            if v == 0:
                # Only openings within reach of the two diverging fronts.
                if abs(c - sc) <= max(0, r - sr):
                    g[r][c] = 2
    # Fill the expanding wedge in zero rows; preserve all 8 cells.
    for r in range(sr + 1, h):
        d = r - sr
        for c in range(max(0, sc - d), min(w, sc + d + 1)):
            if g[r][c] == 0:
                g[r][c] = 2
    return g
