 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    walls = [r for r, row in enumerate(g) if 8 in row]
    if not walls:
        return g

    holes = {r: [c for c, value in enumerate(g[r]) if value == 0] for r in walls}
    # Color each opening in the horizontal barriers.
    for r in walls:
        for c in holes[r]:
            g[r][c] = 2

    sr, sc = next((r, c) for r in range(h) for c in range(w) if grid[r][c] == 2)

    # Join the source to the first barrier's openings in the blank row above.
    first = walls[0]
    if first > 0:
        first_holes = holes[first]
        lo = min([sc] + first_holes)
        hi = max([sc] + first_holes)
        for c in range(lo, hi + 1):
            if g[first - 1][c] == 0:
                g[first - 1][c] = 2

    # Trace the successive gaps: first a vertical/point trail from the previous
    # barrier, then widen across the open band before the next barrier.
    for i in range(len(walls) - 1):
        r, nr = walls[i], walls[i + 1]
        hs = holes[r]
        if not hs:
            continue
        lo, hi = min(hs), max(hs)
        for rr in range(r + 1, nr):
            if rr == nr - 1:
                # The leading edge reaches the next barrier's opening span.
                nxt = holes[nr]
                if nxt:
                    a, b = min(nxt), max(nxt)
                    for c in range(a, b + 1):
                        if g[rr][c] == 0:
                            g[rr][c] = 2
            elif rr == r + 1:
                for c in hs:
                    if g[rr][c] == 0:
                        g[rr][c] = 2
            else:
                # Expand the trail to fill the open row between the barriers.
                for c in range(w):
                    if g[rr][c] == 0:
                        g[rr][c] = 2

    # After the final barrier, extend its openings downward as straight tracks.
    last = walls[-1]
    for c in holes[last]:
        for r in range(last + 1, h):
            if g[r][c] == 0:
                g[r][c] = 2
    return g
