 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seed_r, seed_c = next((r, c) for r in range(h) for c in range(w) if g[r][c] == 2)
    wall_rows = [r for r, row in enumerate(g) if 8 in row]
    openings = {r: [c for c, value in enumerate(g[r]) if value == 0] for r in wall_rows}

    # Color the openings in the barriers that the beam encounters below its seed.
    for r in wall_rows:
        if r > seed_r:
            for c in openings[r]:
                g[r][c] = 2

    # Join the source to the first opening, then join successive opening spans
    # through the clear bands between horizontal barriers.
    if wall_rows:
        first = wall_rows[0]
        if first > seed_r and openings[first]:
            lo = min(seed_c, min(openings[first]))
            hi = max(seed_c, max(openings[first]))
            for c in range(lo, hi + 1):
                if g[first - 1][c] == 0:
                    g[first - 1][c] = 2
        for i in range(len(wall_rows) - 1):
            r, nr = wall_rows[i], wall_rows[i + 1]
            a, b = openings[r], openings[nr]
