 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seed_r, seed_c = next((r, c) for r in range(h) for c in range(w) if g[r][c] == 2)
    walls = [r for r, row in enumerate(g) if 8 in row and r > seed_r]
    holes = {r: [c for c, v in enumerate(g[r]) if v == 0] for r in walls}

    def paint(row, cols):
        if not cols:
            return
        lo, hi = max(0, min(cols)), min(w - 1, max(cols))
        for c in range(lo, hi + 1):
            if g[row][c] == 0:
                g[row][c] = 2

    if not walls:
        return g

    # Connect the source to the first opening span, then mark each barrier's gaps.
    first = walls[0]
    paint(first - 1, [seed_c] + holes[first])
    for r in walls:
        for c in holes[r]:
            g[r][c] = 2

    # In each band, vertical tracks follow the current openings; the last row
    # before the next barrier joins across the next barrier's opening span.
    for i in range(len(walls) - 1):
        r, nr = walls[i], walls[i + 1]
        gap = nr - r
        if gap <= 1:
            continue
        current_holes = holes[r]
        next_holes = holes[nr]
        for rr in range(r + 1, nr - 1):
            for c in current_holes:
                if g[rr][c] == 0:
                    g[rr][c] = 2
        if next_holes:
            paint(nr - 1, next_holes)

    # Extend the last barrier's openings down to the grid edge.
    last = walls[-1]
    for c in holes[last]:
        for r in range(last + 1, h):
            if g[r][c] == 0:
                g[r][c] = 2
    return g
