 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seed_r = next(r for r in range(h) for c in range(w) if g[r][c] == 2)
    seed_c = next(c for c in range(w) if g[seed_r][c] == 2)
    walls = [r for r, row in enumerate(g) if 8 in row and r > seed_r]
    if not walls:
        return g
    holes = {r: [c for c, value in enumerate(g[r]) if value == 0] for r in walls}

    # First open band connects the marker to the first barrier opening.
    first = walls[0]
    if holes[first] and first > 0:
        lo = min([seed_c] + holes[first])
        hi = max([seed_c] + holes[first])
        for c in range(lo, hi + 1):
            if g[first - 1][c] == 0:
                g[first - 1][c] = 2
    for c in holes[first]:
        g[first][c] = 2

    # Each successive gap fans from one barrier's openings toward the next.
    for i in range(len(walls) - 1):
        r, nr = walls[i], walls[i + 1]
        current, nxt = holes[r], holes[nr]
        gap = nr - r - 1
        if gap <= 0:
            continue
        if gap == 1:
            # Connect the current and next opening spans on the single free row.
            cols = current + nxt
            if cols:
                for c in range(min(cols), max(cols) + 1):
                    if g[r + 1][c] == 0:
                        g[r + 1][c] = 2
        else:
            # First row preserves the current openings as vertical tracks.
            for c in current:
                if g[r + 1][c] == 0:
                    g[r + 1][c] = 2
            # Further rows expand the hull of those tracks by two cells per row.
            if current:
                lo, hi = min(current), max(current)
                for k, rr in enumerate(range(r + 2, nr), start=1):
                    left = max(0, lo - 2 * k)
                    right = min(w - 1, hi + 2 * k)
                    for c in range(left, right + 1):
                        if g[rr][c] == 0:
                            g[rr][c] = 2
        for c in nxt:
            g[nr][c] = 2

    # Continue the final barrier's openings as vertical tracks to the bottom.
    last = walls[-1]
    for c in holes[last]:
        for r in range(last + 1, h):
            if g[r][c] == 0:
                g[r][c] = 2
    return g
