 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seed_r, seed_c = next((r, c) for r in range(h) for c in range(w) if g[r][c] == 2)
    walls = [r for r in range(seed_r + 1, h) if 8 in g[r]]
    openings = {r: [c for c, value in enumerate(g[r]) if value == 0] for r in walls}

    def mark(r, c):
        if g[r][c] == 0:
            g[r][c] = 2

    def span(r, cols):
        if cols:
            for c in range(min(cols), max(cols) + 1):
                mark(r, c)

    if not walls:
        return g

    # The marker reaches the openings in the first barrier.
    first = walls[0]
    span(first - 1, [seed_c] + openings[first])
    for c in openings[first]:
        mark(first, c)

    # Between each pair of barriers, continue tracks through their gaps. The
    # broad middle row fans across the open space; the row before the next
    # barrier connects its gap locations.
    for i in range(len(walls) - 1):
        r, nr = walls[i], walls[i + 1]
        current, nxt = openings[r], openings[nr]
        free = list(range(r + 1, nr))
        if not free:
            continue
        if len(free) == 1:
            span(free[0], current + nxt)
        else:
            for c in current:
                mark(free[0], c)
            for rr in free[1:-1]:
                for c in range(w):
                    mark(rr, c)
            span(free[-1], nxt)
        for c in nxt:
            mark(nr, c)

    # The final barrier openings continue as vertical trails to the bottom.
    last = walls[-1]
    for c in openings[last]:
        for r in range(last + 1, h):
            mark(r, c)
    return g
